package com.powercms.cms.sitepackage.entity;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="site_drop_zone", uniqueConstraints=@UniqueConstraint(columnNames={"template_id","zone_key"}))
public class SiteDropZoneEntity { @Id private UUID id; @Column(name="template_id",nullable=false) private UUID templateId; @Column(name="zone_key",nullable=false,length=200) private String zoneKey; @Column(name="container_id") private UUID containerId; @Column(name="sort_order",nullable=false) private int sortOrder; @Column(nullable=false,columnDefinition="text") private String config="{}"; @PrePersist void create(){if(id==null)id=UUID.randomUUID();} public UUID getId(){return id;} public void setId(UUID v){id=v;} public UUID getTemplateId(){return templateId;} public void setTemplateId(UUID v){templateId=v;} public String getZoneKey(){return zoneKey;} public void setZoneKey(String v){zoneKey=v;} public UUID getContainerId(){return containerId;} public void setContainerId(UUID v){containerId=v;} public int getSortOrder(){return sortOrder;} public void setSortOrder(int v){sortOrder=v;} public String getConfig(){return config;} public void setConfig(String v){config=v;} }